-- 0077 適用後チェック（SELECT1文・読み取り専用）
with r(ord, level, item, detail) as (values
 (1, case when not has_function_privilege('authenticated', to_regprocedure('public.save_stylist_profile_v3(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,text,date,text)'), 'execute') and not has_function_privilege('anon', to_regprocedure('public.save_stylist_profile_v3(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,text,date,text)'), 'execute') and not has_function_privilege('service_role', to_regprocedure('public.save_stylist_profile_v3(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,text,date,text)'), 'execute') then 'PASS' else 'FAIL' end, 'v3は誰も実行できない（閉じた）', ''),
 (2, case when has_function_privilege('authenticated', to_regprocedure('public.save_stylist_profile_v4(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,integer,text)'), 'execute') then 'PASS' else 'FAIL' end, 'v4は authenticated が実行できる', ''),
 (3, case when not has_function_privilege('authenticated', to_regprocedure('public.save_stylist_profile_v2(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text)'), 'execute') and not has_function_privilege('authenticated', to_regprocedure('public.set_stylist_career_phase(text,date,text,date,text)'), 'execute') then 'PASS' else 'FAIL' end, '旧経路（v2・set_stylist_career_phase）も閉じたまま', ''),
 (4, case when has_function_privilege('authenticated', to_regprocedure('public.set_stylist_value_priorities(text[])'), 'execute') then 'PASS' else 'FAIL' end, '0072の専用保存は実行できる（維持）', ''),
 (5, 'INFO', '立場の内訳（0077はデータを変更しない）', (select count(*) filter (where career_phase is null)::text||' / '||count(*) filter (where career_phase='student')::text||' / '||count(*) filter (where career_phase='new_graduate')::text||' / '||count(*) filter (where career_phase='experienced')::text||' / '||count(*) filter (where career_phase='blank')::text from public.stylist_profiles))
)
select ord, level, item, detail from (select ord::text as ord, level, item, detail from r
union all
select '99', case when (select count(*) from r where level='FAIL')=0 then 'PASS' else 'FAIL' end, '総合判定（INFO '||(select count(*) from r where level='INFO')||'件は人が確認）', 'FAIL '||(select count(*) from r where level='FAIL')||'件'
) t order by ord::int;
